'use strict';
(async()=>{
  const root=document.querySelector('#challenge'),query=new URLSearchParams(location.search);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clock=ms=>{const s=Math.max(0,Math.floor(ms/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
  function notice(s){const e=document.querySelector('#game-message');e.textContent=s;e.classList.add('show');clearTimeout(e._timer);e._timer=setTimeout(()=>e.classList.remove('show'),5000);}
  try{
    const response=await fetch('../bank.json?v=20261023-2');if(!response.ok)throw new Error('The game cards could not be loaded. Refresh and try again.');
    const bank=await response.json(),g=bank.games.find(g=>g.id===query.get('game'))||bank.games[0];
    assignViews(g,bank.games.indexOf(g));
    const storageKey='bd-challenge-v1-'+g.id,live=new NaivashaRace.RaceConnection(g.id);
    const fresh=()=>({screen:'setup',team:'',sector:query.get('w')==='secretariats'?'he':'health',room:query.get('room')||'',i:0,answers:[],score:0,startedAt:0,finishedAt:0,generation:0,live:false});
    let S=fresh(),selection=[],order=[],busy=false,leaders=[],lastLeaders=0;
    try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved&&Array.isArray(saved.answers)&&saved.answers.length<=g.questions.length&&Number.isInteger(saved.i)&&saved.i>=0&&saved.i<g.questions.length)S={...S,...saved};}catch{}
    if(query.get('room')&&query.get('room').toUpperCase()!==S.room){S={...fresh(),team:S.team};}
    if(query.has('w')&&S.screen==='setup')S.sector=query.get('w')==='secretariats'?'he':'health';
    const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(S));}catch{notice('This browser cannot save. Keep this tab open during the game.');}};
    const elapsed=()=>S.live&&live.active()?live.elapsed():Math.max(0,(S.finishedAt||Date.now())-(S.startedAt||Date.now()));
    const correct=()=>S.answers.filter(a=>a.correct).length;
    const streak=()=>{let n=0;for(let i=S.answers.length-1;i>=0&&S.answers[i].correct;i--)n++;return n;};
    // Display order only. data-choice and every stored selection stay in the
    // bank's original index space, so server scoring is unaffected. The point is
    // that the correct choice is not always in the same position.
    function shuffleFor(q,attempt){let h=2166136261;const seed='bd2026:'+attempt+':'+q.id;for(let i=0;i<seed.length;i++){h^=seed.charCodeAt(i);h=Math.imul(h,16777619)>>>0;}const rnd=()=>{h^=h<<13;h>>>=0;h^=h>>>17;h^=h<<5;h>>>=0;return h/4294967296;};const v=q.options.map((_,i)=>i);for(let i=v.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[v[i],v[j]]=[v[j],v[i]];}return v;}
    function assignViews(game,gameIndex){const used={};
      // Each game gets a different target position-pair for its two-choice round,
      // so a team that has played another game cannot carry a guess across.
      const PAIRSETS=['01','02','03','12','13','23'];const pairTarget=PAIRSETS[(gameIndex>=0?gameIndex:0)%PAIRSETS.length];
      for(const q of game.questions){let best=null,bestCost=Infinity;
        for(let attempt=0;attempt<24;attempt++){const v=shuffleFor(q,attempt);
          if(q.kind==='order'){if(v.every((n,i)=>n===q.answer[i]))continue;best=v;break;}
          const letters=q.answer.map(o=>v.indexOf(o));
          if(q.kind==='pair'&&[...letters].sort().join('')===pairTarget){best=v;break;}
          const cost=Math.max(...letters.map(L=>used[L]||0))*100+letters.reduce((s,L)=>s+(used[L]||0),0);
          if(cost<bestCost){bestCost=cost;best=v;if(cost===0&&q.kind!=='pair')break;}}
        best=best||q.options.map((_,i)=>i);
        if(q.kind!=='order')q.answer.forEach(o=>{const L=best.indexOf(o);used[L]=(used[L]||0)+1;});
        q._view=best;}}
    function viewOrder(q){return q._view||q.options.map((_,i)=>i);}
    function apply(team){const identity={team:team.name,sector:team.sector,room:team.room,live:true};S={...fresh(),...team.state,...identity,generation:team.generation,startedAt:team.startedAt,finishedAt:team.finishedAt};if(!Object.keys(team.state||{}).length)S.screen='card';selection=[];order=[];save();}
    live.onReset=team=>{apply(team);render();notice('The facilitator reset your game. Your team is ready at question one.');};
    live.onStatus=()=>{paintStatus();};
    live.onAck=team=>{if(!S.live)return;S.startedAt=team.startedAt;S.finishedAt=team.finishedAt;save();};
    function publish(){if(S.live)live.publish({i:S.i,screen:S.screen,answers:S.answers,score:S.score});}
    function hud(){return `<div class="game-hud"><div><small>${esc(S.team)}${S.live?' · '+esc(S.room):' · practice'}</small><strong>${esc(g.title)}</strong></div><div><small>Points</small><strong>${S.score} / ${g.questions.length*10}</strong></div><div><small>Right / wrong</small><strong>${correct()} / ${S.answers.length-correct()}</strong></div><div><small>Elapsed</small><strong id="elapsed">${clock(elapsed())}</strong></div></div><p id="live-status" class="game-status" aria-live="polite"></p>`;}
    function setup(){return `<section class="game-intro"><div class="eyebrow">Workshop challenge · ${esc(g.strap)}</div><h1>${esc(g.title)}</h1><p>${esc(g.description)}</p></section><div class="challenge-hero"><div><strong>${g.questions.length} rounds</strong><small>Choices, pairs and sequencing</small></div><div><strong>${g.questions.length*10} points</strong><small>Accuracy first · time breaks a tie</small></div><div><strong>~${g.minutes} min</strong><small>Then discuss the decisions</small></div></div><form id="setup" class="play-setup card"><label class="field">Team alias<input name="team" value="${esc(S.team)}" required minlength="2" maxlength="24" autocomplete="off" placeholder="e.g. Table 4"><small>Use one shared device per team. No personal names needed.</small></label><label class="field">Workshop<select name="sector"><option value="health" ${S.sector==='health'?'selected':''}>01 · Tripartite institutions</option><option value="he" ${S.sector==='he'?'selected':''}>02 · Secretariat capacities</option></select></label>${g.practice?'<div class="field"><strong style="display:block;margin-bottom:4px">Practice only</strong><small>This challenge is not yet on the live competition service, so there is no session code. Everything else works: the rounds, the feedback and the downloadable result.</small></div>':`<label class="field">Session code<input name="room" value="${esc(S.room)}" maxlength="8" autocomplete="off" placeholder="Leave blank for practice" style="text-transform:uppercase;letter-spacing:.12em"><small>Eight characters, letters A–Z and digits 2–9 — there is no zero and no one. Use the same code as the other teams, or leave it blank to practise.</small></label>`}<p class="muted">10 points for a fully correct round. In a two-choice round, each correct choice earns 5 points. The right/wrong totals count whole rounds; a partly correct round counts as wrong. ${g.practice?'This practice result is saved on this device.':'Live scores are checked by the server.'}</p><p class="error" id="setup-error" role="alert"></p><div class="actions"><button class="button" type="submit">${S.room&&!g.practice?'Join the live challenge':'Start the challenge'} →</button><a class="button secondary" href="../../#games">Choose another game</a></div></form>`;}
    function card(){const q=g.questions[S.i],a=S.answers[S.i],reveal=!!a;const view=viewOrder(q);if(!order.length)order=[...view];
      const options=q.kind==='order'?`<p class="muted">Move the steps into order, then lock your sequence.</p><ol class="order-list">${(reveal?a.selection:order).map((n,i)=>`<li class="order-row"><strong>${i+1}</strong><span>${esc(q.options[n])}</span>${!reveal?`<button class="button small secondary" type="button" data-move="${i}" data-delta="-1" aria-label="Move step ${i+1} up" ${i===0?'disabled':''}>↑</button><button class="button small secondary" type="button" data-move="${i}" data-delta="1" aria-label="Move step ${i+1} down" ${i===order.length-1?'disabled':''}>↓</button>`:''}</li>`).join('')}</ol>`:`<p class="muted">${q.kind==='pair'?'Choose exactly TWO moves.':'Choose one answer.'}</p><div class="answer-list" role="group" aria-label="Answer choices">${view.map((i,pos)=>`<button type="button" class="answer-choice ${reveal&&q.answer.includes(i)?'answer-right':reveal&&a.selection.includes(i)?'answer-wrong':''}" data-choice="${i}" aria-pressed="${reveal?a.selection.includes(i):selection.includes(i)}" ${reveal?'disabled':''}><span>${String.fromCharCode(65+pos)}</span><span>${esc(q.options[i])}${reveal&&q.answer.includes(i)?' <strong>✓ Correct choice</strong>':''}</span></button>`).join('')}</div>`;
      return hud()+`<div class="game-progress" aria-label="${S.answers.length} of ${g.questions.length} rounds answered"><span style="width:${S.answers.length/g.questions.length*100}%"></span></div><section class="question-card"><div class="eyebrow">Question ${S.i+1} / ${g.questions.length} · ${esc(q.section)}</div><h2>${esc(q.prompt)}</h2>${options}${reveal?`<div class="feedback ${a.correct?'':'partial'}" role="status"><h3>${a.correct?'Good call!':a.points?'Partly there.':'A useful lesson.'} +${a.points} points ${streak()>=2?`<small class="streak">· ${streak()} rounds right in a row</small>`:''}</h3><p>${esc(q.why)}</p>${q.kind==='order'?`<p style="margin-top:10px"><strong>Suggested sequence:</strong> ${q.answer.map(n=>esc(q.options[n])).join(' → ')}</p>`:''}</div>`:''}<p class="error" id="answer-error" role="alert"></p><div class="actions">${reveal?`<button class="button" id="next">${S.i===g.questions.length-1?'See the results':'Next round'} →</button>`:`<button class="button" id="lock" ${q.kind!=='order'&&selection.length!==(q.kind==='pair'?2:1)?'disabled':''}>Lock answer →</button>`}<button class="button secondary" id="leave">${S.live?'Leave live table':'Back to setup'}</button></div></section>${S.live?'<section id="standings" class="live-mini" aria-label="Live team standings"></section>':''}`;
    }
    function final(){return hud()+`<section class="question-card"><div class="eyebrow">Challenge complete · ${esc(g.strap)}</div><h1>${esc(S.team)}, mission complete.</h1><div class="results-number">${S.score} <small>/ ${g.questions.length*10}</small></div><p><strong>${correct()} right · ${S.answers.length-correct()} wrong · ${clock(elapsed())}</strong></p><p>${S.live?'Your live result is sent to the facilitator board. Check the connection message above before closing this tab.':'This practice result is saved on this device.'}</p><div class="actions"><button class="button secondary" id="export">Download result ↓</button><a class="button" href="../../#games">Back to the game desk →</a>${!S.live?'<button class="button secondary" id="again">Play again</button>':''}</div></section><section class="card debrief"><div class="eyebrow">The conversation after the race</div><h2>Take it to your institution</h2><ol>${g.debrief.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>${S.live?'<p>The facilitator can reset one team or all teams. Keep this tab open to receive a reset.</p>':''}</section><section class="card debrief"><h2>Review the decisions</h2>${g.questions.map((q,i)=>`<details><summary>${i+1}. ${esc(q.section)} · ${S.answers[i]?.correct?'Right':'Review'} · ${S.answers[i]?.points||0} points</summary><p>${esc(q.prompt)}</p><p>${esc(q.why)}</p></details>`).join('')}</section>${S.live?'<section id="standings" class="live-mini" aria-label="Live team standings"></section>':''}`;}
    function render(){document.title=g.title+' · Bangladesh 2026';root.innerHTML=S.screen==='setup'?setup():S.screen==='final'?final():card();wire();paintStatus();paintStandings();}
    function paintStatus(){const el=document.querySelector('#live-status');if(!el)return;el.textContent=S.live?live.label()+(live.message?' · '+live.message:''):'Practice · saved on this device';el.classList.toggle('offline',S.live&&live.status==='offline');}
    function paintStandings(){const el=document.querySelector('#standings');if(!el)return;if(!leaders.length){el.innerHTML='<strong>Live table</strong><p>Waiting for the next scoreboard update…</p>';return;}const sorted=[...leaders].sort((a,b)=>b.metrics.score-a.metrics.score||(a.finishedAt||Date.now())-a.startedAt-((b.finishedAt||Date.now())-b.startedAt));el.innerHTML='<strong>Live table · '+leaders.length+' team'+(leaders.length===1?'':'s')+'</strong><ol>'+sorted.slice(0,5).map(t=>`<li>${esc(t.name)} <small>· ${t.metrics.answered}/${t.metrics.steps} answered</small><strong>${t.metrics.score} pts</strong></li>`).join('')+'</ol>';}
    function wire(){
      document.querySelector('#setup')?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=e.target,team=f.elements.team.value.trim(),room=g.practice?'':(f.elements.room?f.elements.room.value.trim().toUpperCase():''),sector=f.elements.sector.value;if(team.length<2)return;busy=true;f.querySelector('button').disabled=true;try{S={...fresh(),team,room,sector};if(room){const t=await live.join({room,name:team,sector});apply(t);}else{live.stop();S={...S,screen:'card',startedAt:Date.now()};}selection=[];order=[];save();render();root.focus({preventScroll:true});}catch(error){document.querySelector('#setup-error').textContent=error.message;f.querySelector('button').disabled=false;}finally{busy=false;}});
      document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.choice),q=g.questions[S.i];selection=q.kind==='pair'?(selection.includes(n)?selection.filter(x=>x!==n):selection.length<2?[...selection,n]:selection):[n];render();}));
      document.querySelectorAll('[data-move]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.move),j=i+Number(b.dataset.delta);[order[i],order[j]]=[order[j],order[i]];render();}));
      document.querySelector('#lock')?.addEventListener('click',()=>{if(S.answers[S.i])return;const q=g.questions[S.i],pick=q.kind==='order'?[...order]:[...selection];if(pick.length!==q.answer.length)return;const right=q.kind==='order'?pick.every((n,i)=>n===q.answer[i]):pick.every(n=>q.answer.includes(n)),points=q.kind==='pair'?pick.filter(n=>q.answer.includes(n)).length*5:right?10:0;S.answers.push({selection:pick,correct:right,points});S.score=S.answers.reduce((s,a)=>s+a.points,0);S.screen='reveal';if(S.answers.length===g.questions.length)S.finishedAt=Date.now();save();publish();render();document.querySelector('.feedback')?.scrollIntoView({block:'nearest',behavior:'smooth'});});
      document.querySelector('#next')?.addEventListener('click',()=>{if(S.i===g.questions.length-1)S.screen='final';else{S.i++;S.screen='card';}selection=[];order=[];save();publish();render();root.focus({preventScroll:true});});
      document.querySelector('#leave')?.addEventListener('click',()=>{if(S.live&&!confirm('Leave the live table on this device? Your result stays on the facilitator board. Rejoin with the same code to resume.'))return;live.stop();S.screen='setup';S.live=false;save();render();});
      document.querySelector('#again')?.addEventListener('click',()=>{if(confirm('Start a new practice attempt? Download your result first if you want a copy.')){S={...fresh(),team:S.team,sector:S.sector,room:''};save();selection=[];order=[];render();}});
      document.querySelector('#export')?.addEventListener('click',()=>{const result={game:g.title,team:S.team,workshop:S.sector==='he'?'secretariats':'institutions',session:S.live?S.room:null,points:S.score,max:g.questions.length*10,right:correct(),wrong:S.answers.length-correct(),elapsedSeconds:Math.round(elapsed()/1000),answers:S.answers,exportedAt:new Date().toISOString()};const u=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='Bangladesh_'+g.id+'_result.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);});
    }
    if(S.live&&live.connection?.room===S.room){render();const team=await live.resume();if(team){if(!live.pending)apply(team);render();}else notice('Could not reconnect yet. Progress is saved here; keep this tab open.');}else{S.live=false;render();}
    setInterval(async()=>{const el=document.querySelector('#elapsed');if(el)el.textContent=clock(elapsed());if(S.live&&live.active()&&Date.now()-lastLeaders>5000){lastLeaders=Date.now();try{leaders=(await live.request('standings')).teams;paintStandings();}catch{}}},1000);
  }catch(error){root.innerHTML='<section class="card"><h1>The challenge could not open</h1><p>'+esc(error.message)+'</p><a class="button" href="../../#games">Return to the game desk</a></section>';}
})();
